import React, { useEffect, useState } from 'react';
import { View } from '@vkontakte/vkui';
import Welcome from './panels/Welcome';
import Test from './panels/Test';
import Result from './panels/Result';
import Subscribe from './panels/Subscribe';
import Pay from './panels/Pay';
import Chat from './panels/Chat';
import '@vkontakte/vkui/dist/vkui.css';
import './app.css';

const App = () => {
  // activePanel: welcome, test, result, subscribe, pay, chat
  const [activePanel, setActivePanel] = useState('welcome');
  const [isSubscribed, setIsSubscribed] = useState(() => {
    try {
      return localStorage.getItem('isSubscribed') === '1';
    } catch (e) {
      return false;
    }
  });

  const [testAnswers, setTestAnswers] = useState([]); // array of selected indices

  useEffect(() => {
    // if subscription changed elsewhere, persist
    try {
      localStorage.setItem('isSubscribed', isSubscribed ? '1' : '0');
    } catch (e) {}
  }, [isSubscribed]);

  const go = (panelId) => setActivePanel(panelId);

  return (
    <View activePanel={activePanel} popout={null}>
      <Welcome id="welcome" go={go} />
      <Test id="test" go={go} setTestAnswers={setTestAnswers} />
      <Result id="result" go={go} testAnswers={testAnswers} />
      <Subscribe id="subscribe" go={go} isSubscribed={isSubscribed} />
      <Pay id="pay" go={go} setIsSubscribed={setIsSubscribed} />
      <Chat id="chat" go={go} isSubscribed={isSubscribed} />
    </View>
  );
};

export default App;
