import React, { useState } from 'react';
import { Panel, PanelHeader, Group, Div, Title, Text, Button, Spinner } from '@vkontakte/vkui';

const Pay = ({ id, go, setIsSubscribed }) => {
  const [loading, setLoading] = useState(false);

  const doPay = () => {
    setLoading(true);
    // симуляция вызова платежной системы
    setTimeout(() => {
      setLoading(false);
      setIsSubscribed(true);
      // переход в чат после оплаты
      go('chat');
    }, 1200);
  };

  return (
    <Panel id={id} style={{ minHeight: '100vh', background: 'var(--lavender,#EDE7FF)' }}>
      <PanelHeader>Оплата</PanelHeader>

      <Group style={{ padding: 16 }}>
        <Div style={{ textAlign: 'center' }}>
          <Title level="2">Оплата подписки</Title>
          <Text style={{ marginTop: 8 }}>Вы будете перенаправлены на защищённую страницу оплаты (здесь — демо).</Text>
        </Div>

        <Div>
          <Button size="l" stretched onClick={doPay} disabled={loading}>
            {loading ? <><Spinner size="small" /> Обработка...</> : 'Оплатить 990 ₽/мес'}
          </Button>
        </Div>

        <Div>
          <Button size="m" mode="secondary" onClick={() => go('subscribe')}>Назад</Button>
        </Div>
      </Group>
    </Panel>
  );
};

export default Pay;
