import React, { useState } from 'react';
import { Panel, PanelHeader, Group, Div, Button, Avatar, Title, Radio, FormItem } from '@vkontakte/vkui';

const questions = [
  {
    id: 1,
    text: 'Как часто вы чувствуете напряжение в течение дня?',
    options: ['Почти не чувствую', 'Иногда', 'Часто', 'Почти всегда']
  },
  {
    id: 2,
    text: 'Что сейчас ощущаете сильнее всего?',
    options: ['Тревога', 'Усталость', 'Раздражительность', 'Эмоциональное опустошение']
  },
  {
    id: 3,
    text: 'Как вы обычно справляетесь со стрессом?',
    options: ['Отвлекаюсь (соцсети, сериалы)', 'Разговариваю с кем-то', 'Стараюсь игнорировать', 'Не знаю, сложно справляться']
  },
  {
    id: 4,
    text: 'Хотели бы вы получать поддержку и разбор ваших мыслей 24/7?',
    options: ['Да', 'Скорее да', 'Скорее нет', 'Нет']
  }
];

const Test = ({ id, go, setTestAnswers }) => {
  const [idx, setIdx] = useState(0);
  const [answers, setAnswers] = useState(Array(questions.length).fill(null));

  const handleSelect = (optionIndex) => {
    const copy = [...answers];
    copy[idx] = optionIndex;
    setAnswers(copy);
  };

  const next = () => {
    if (answers[idx] == null) return;
    if (idx < questions.length - 1) {
      setIdx(idx + 1);
    } else {
      // finish
      setTestAnswers(answers);
      go('result');
    }
  };

  const prev = () => {
    if (idx > 0) setIdx(idx - 1);
    else go('welcome');
  };

  const q = questions[idx];

  return (
    <Panel id={id} style={{ minHeight: '100vh', background: 'var(--lavender,#EDE7FF)' }}>
      <PanelHeader>Тест: эмоциональное состояние</PanelHeader>

      <Group style={{ padding: 16 }}>
        <Div style={{ textAlign: 'center' }}>
          <Title level="3" weight="2">{`Вопрос ${idx + 1} из ${questions.length}`}</Title>
          <div style={{ marginTop: 12 }}>{q.text}</div>
        </Div>

        <Div>
          <FormItem>
            {q.options.map((opt, i) => (
              <div key={i} style={{ margin: '10px 0' }}>
                <label style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  <input
                    type="radio"
                    name={`q${idx}`}
                    checked={answers[idx] === i}
                    onChange={() => handleSelect(i)}
                  />
                  <span>{opt}</span>
                </label>
              </div>
            ))}
          </FormItem>
        </Div>

        <Div>
          <Button size="l" onClick={next} disabled={answers[idx] == null} stretched>
            {idx < questions.length - 1 ? 'Далее' : 'Показать результат'}
          </Button>
        </Div>

        <Div>
          <Button size="m" mode="secondary" onClick={prev}>Назад</Button>
        </Div>
      </Group>
    </Panel>
  );
};

export default Test;
