import React from 'react';
import { Panel, PanelHeader, Group, Div, Title, Text, Button } from '@vkontakte/vkui';

const analyze = (answers) => {
  // Простая эвристика: если много высоких индексов => сильнее тревога/стресс
  const score = answers.reduce((s, a) => s + (a == null ? 0 : a), 0);
  if (score <= 3) return {
    title: 'Спокойный эмоциональный фон',
    body: 'Судя по ответам, у вас низкий уровень текущего напряжения. Следите за режимом и делайте короткие практики для профилактики.',
    level: 'low'
  };
  if (score <= 6) return {
    title: 'Повышенная нагрузка',
    body: 'У вас периодически накапливается напряжение. Рекомендуем упражнения на дыхание и трёхшаговые рефлексии.',
    level: 'medium'
  };
  return {
    title: 'Высокий уровень напряжения',
    body: 'Вы показываете признаки накопленного стресса и тревоги. Рекомендуется регулярная работа с техниками стабилизации и поддержка между сессиями.',
    level: 'high'
  };
};

const Result = ({ id, go, testAnswers }) => {
  const res = analyze(testAnswers || []);
  return (
    <Panel id={id} style={{ minHeight: '100vh', background: 'var(--lavender,#EDE7FF)' }}>
      <PanelHeader>Результат теста</PanelHeader>

      <Group style={{ padding: 16 }}>
        <Div style={{ textAlign: 'center' }}>
          <Title level="2">{res.title}</Title>
          <Text style={{ marginTop: 12 }}>{res.body}</Text>
        </Div>

        <Div>
          <Title level="3">Что можно сделать прямо сейчас</Title>
          <ul>
            <li>Сделать 3 минуты дыхательной практики (4-4-4)</li>
            <li>Записать 3 вещи, за которые вы благодарны</li>
            <li>Сделать короткую прогулку и посчитать 5 глубоких вдохов</li>
          </ul>
        </Div>

        <Div>
          <Text weight="2">Чтобы получать персональные рекомендации и поддержку 24/7 — оформите подписку.</Text>
        </Div>

        <Div>
          <Button size="l" stretched onClick={() => go('subscribe')}>Оформить подписку — 990 ₽/мес</Button>
        </Div>

        <Div>
          <Button size="m" mode="secondary" onClick={() => go('subscribe')}>Подробнее о подписке</Button>
        </Div>
      </Group>
    </Panel>
  );
};

export default Result;
