import React from 'react';
import { Panel, PanelHeader, Group, Div, Button, Text } from '@vkontakte/vkui';

const Chat = ({ id, isSubscribed, go }) => {
  // iframe URL — используем ваш рабочий вариант с dark=1 и fullscreen=1
  const iframeSrc = 'https://functions.pro-talk.ru/api/v1.0/chatgpt_widget_dialog_api?record_id=recbu9jpdPAyoPqCR&promt_id=46868&lang=ru&fullscreen=1&voice=1&file=0&circle=1&autoplay=1&dark=1';

  return (
    <Panel id={id} style={{ minHeight: '100vh', background: 'var(--lavender,#EDE7FF)' }}>
      <PanelHeader>Чат с ИИ</PanelHeader>

      {!isSubscribed ? (
        <Group style={{ padding: 16 }}>
          <Div style={{ textAlign: 'center' }}>
            <Text weight="2">Доступ к чату открыт только по подписке.</Text>
            <Text style={{ marginTop: 8 }}>Оформите подписку, чтобы получить неограниченный доступ.</Text>
          </Div>

          <Div>
            <Button size="l" stretched onClick={() => go('subscribe')}>Оформить подписку</Button>
          </Div>

          <Div>
            <Button size="m" mode="secondary" onClick={() => go('welcome')}>Назад</Button>
          </Div>
        </Group>
      ) : (
        <Group style={{ height: '100%', padding: 0 }}>
          <iframe
            allow="microphone; autoplay"
            style={{ width: '100%', height: 'calc(100vh - 112px)', border: 0 }}
            src={iframeSrc}
            title="Ассистент Арина"
          />
        </Group>
      )}
    </Panel>
  );
};

export default Chat;
